function livingEnglishLabel(text) {
  if (typeof text !== 'string') return text;
  const trimmed = text.trim();
  let translated = LIVING_ENGLISH_LABELS[trimmed];
  // Preserve decorative icons while translating only a known UI label.
  // This never translates arbitrary names or journal prose by substring.
  if (translated === undefined) {
    const decorated = trimmed.match(/^([^\p{L}\p{N}]*)(.*?)([^\p{L}\p{N}]*)$/u);
    if (decorated && LIVING_ENGLISH_LABELS[decorated[2]] !== undefined)
      translated = decorated[1] + LIVING_ENGLISH_LABELS[decorated[2]] + decorated[3];
  }
  if (translated === undefined) {
    let m;
    if ((m = trimmed.match(/^(.+) nimmt sich tatsächlich Zeit für (.+)\. Der Zugang ist kostenlos\.$/))) translated = `${m[1]} spends time on ${LIVING_ENGLISH_LABELS[m[2]] || m[2]}. Access is free.`;
    else if ((m = trimmed.match(/^Ausgangshintergrund (\d+(?:[.,]\d+)?%) · seit Beginn (\d+(?:[.,]\d+)?) Minuten Praxis$/))) translated = `Starting background ${m[1]} · ${m[2]} minutes of practice since the start`;
    else if ((m = trimmed.match(/^Gerade wichtig: (.+)$/))) translated = `Important right now: ${m[1]}`;
    else if ((m = trimmed.match(/^Zuhause in (.+)$/))) translated = `At home in ${m[1]}`;
    else if ((m = trimmed.match(/^Nähe (\d+(?:[.,]\d+)?)% · Vertrauen (\d+(?:[.,]\d+)?)%(?: · Spannung (\d+(?:[.,]\d+)?)%)?$/))) translated = `Closeness ${m[1]}% · Trust ${m[2]}%${m[3] === undefined ? '' : ` · Tension ${m[3]}%`}`;
    else if ((m = trimmed.match(/^(.+) · die Stadt entdecken$/))) translated = `${m[1]} · explore the town`;
    else if ((m = trimmed.match(/^Wohlbefinden · PERMA (.+)$/))) translated = `Wellbeing · PERMA ${m[1]}`;
    else if ((m = trimmed.match(/^(\d+) Einwohner$/))) translated = `${m[1]} residents`;
    else if ((m = trimmed.match(/^Haus (\d+)$/))) translated = `House ${m[1]}`;
    else if ((m = trimmed.match(/^Nachbarschaft (\d+)$/))) translated = `Neighborhood ${m[1]}`;
    else if ((m = trimmed.match(/^Raum (\d+)$/))) translated = `Room ${m[1]}`;
    else if ((m = trimmed.match(/^([\d,.]+) Sims?$/))) translated = `${m[1]} Sim${m[1] === '1' ? '' : 's'}`;
    else if ((m = trimmed.match(/^(.+) · (\d+) Jahre$/))) translated = `${m[1]} · age ${m[2]}`;
    else if ((m = trimmed.match(/^Platz für (\d+) Personen$/))) translated = `Capacity: ${m[1]} people`;
    else if ((m = trimmed.match(/^Für (\d+) Personen$/))) translated = `For ${m[1]} people`;
    else if ((m = trimmed.match(/^([\d,.]+) offene Stellen$/))) translated = `${m[1]} open positions`;
    else if ((m = trimmed.match(/^([\d,.]+) Stunden am Arbeitstag$/))) translated = `${m[1]} hours per workday`;
    else if ((m = trimmed.match(/^([\d,.]+) Jahre$/))) translated = `${m[1]} years`;
    else if ((m = trimmed.match(/^([\d,.]+) Personen$/))) translated = `${m[1]} people`;
    else if ((m = trimmed.match(/^([\d,.]+) Portionen$/))) translated = `${m[1]} portions`;
    else if ((m = trimmed.match(/^([\d,.]+) Anker$/))) translated = `${m[1]} anchors`;
    else if ((m = trimmed.match(/^([\d,.]+) von ([\d,.]+) Sims$/))) translated = `${m[1]} of ${m[2]} Sims`;
    else if ((m = trimmed.match(/^([\d,.]+) Kontakte$/))) translated = `${m[1]} contacts`;
    else if ((m = trimmed.match(/^([\d,.]+) von ([\d,.]+) Sims$/))) translated = `${m[1]} of ${m[2]} Sims`;
    else if ((m = trimmed.match(/^([\d,.]+) Sims · ([\d,.]+) Haushalte$/))) translated = `${m[1]} Sims · ${m[2]} households`;
    else if ((m = trimmed.match(/^Schritt ([\d,.]+) · zuletzt ([\d,.]+) Sims in ([\d,.]+) Erzählfeldern\.$/))) translated = `Step ${m[1]} · most recently, ${m[2]} Sims across ${m[3]} story fields.`;
    else if ((m = trimmed.match(/^([\d,.]+)–([\d,.]+) \/ ([\d,.]+) Kontakte$/))) translated = `${m[1]}–${m[2]} / ${m[3]} contacts`;
    else if ((m = trimmed.match(/^([\d,.]+)–([\d,.]+) \/ ([\d,.]+) Anker$/))) translated = `${m[1]}–${m[2]} / ${m[3]} anchors`;
    else if ((m = trimmed.match(/^([\d,.]+)–([\d,.]+) \/ ([\d,.]+) Sims$/))) translated = `${m[1]}–${m[2]} / ${m[3]} Sims`;
  }
  if (translated === undefined) return text;
  const start = text.match(/^\s*/)[0], end = text.match(/\s*$/)[0];
  return start + translated + end;
}

